const profileKey="marketpilot-profile-v1";function getProfile(){try{return JSON.parse(localStorage.getItem(profileKey)||"{}")}catch(e){return {}}}function loadProfile(){const p=getProfile();$("mpName").value=p.name||"";$("mpLevel").value=p.level||"beginner";$("mpFocus").value=p.focus||"crypto";$("mpLanguage").value=p.language||"English";$("mpProfileTitle").textContent=p.name||"Local workspace";}$("mpSaveProfile").addEventListener("click",()=>{const p={name:$("mpName").value.trim(),level:$("mpLevel").value,focus:$("mpFocus").value,language:$("mpLanguage").value,savedAt:new Date().toISOString()};localStorage.setItem(profileKey,JSON.stringify(p));$("mpProfileTitle").textContent=p.name||"Local workspace";$("mpProfileStatus").textContent="Preferences saved on this device. No account has been created.";});$("mpExport").addEventListener("click",()=>{const blob=new Blob([JSON.stringify({app:"MarketPilot AI",exportedAt:new Date().toISOString(),profile:getProfile()},null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="marketpilot-preferences.json";a.click();URL.revokeObjectURL(url);});loadProfile();$("mpBackend").textContent=API_BASE?"MarketPilot AI endpoint configured":"MarketPilot AI URL missing";$("mpDate").textContent=new Date().toLocaleDateString(undefined,{month:"short",day:"numeric",year:"numeric"});
function renderAnswer(container,value){
container.classList.add("mp-answer-block");
function extractText(input,depth=0){
 if(depth>8||input==null)return "";
 if(typeof input==="string"){
  const text=input.replace(/\\r/g,"").trim();
  if(!text)return "";
  if((text.startsWith("{")&&text.endsWith("}"))||(text.startsWith("[")&&text.endsWith("]"))){
   try{const parsed=JSON.parse(text);const nested=extractText(parsed,depth+1);if(nested)return nested;if(parsed&&typeof parsed==="object"&&("choices" in parsed||"candidates" in parsed||"reasoning" in parsed||"reasoning_content" in parsed))return "";}catch(_){}
  }
  return text;
 }
 if(Array.isArray(input))return input.map(item=>extractText(item,depth+1)).filter(Boolean).join("\\n").trim();
 if(typeof input==="object"){
  const direct=[
   input.choices?.[0]?.message?.content,
   input.choices?.[0]?.text,
   input.candidates?.[0]?.content?.parts?.map(part=>part?.text||"").join("\\n"),
   input.output_text,
   input.answer,
   input.response,
   input.generated_text,
   input.text,
   input.content?.parts?.map(part=>part?.text||"").join("\\n"),
   input.content,
   input.message?.content,
   input.result
  ];
  for(const candidate of direct){if(candidate==null)continue;const text=extractText(candidate,depth+1);if(text)return text;}
  for(const key of ["data","output","choices","candidates","messages","parts","sections"]){
   if(input[key]==null)continue;
   const text=extractText(input[key],depth+1);if(text)return text;
  }
 }
 return "";
}
let source=extractText(value);
if(!source)source="The AI service returned a structured response without readable final text. Please retry; if this continues, the provider response needs investigation.";
const lines=source.replace(/^#{1,6}(?=\\S)/gm,"# ").split("\\n");
let list=null,listType="";
for(const raw of lines){
 const line=raw.trim();
 if(!line){list=null;listType="";continue;}
 const heading=line.match(/^#{1,3}\\s*(.+)/);
 if(heading){list=null;const h=document.createElement("h3");h.textContent=heading[1].replace(/\\*\\*/g,"");container.appendChild(h);continue;}
 const bullet=line.match(/^(?:[-*•])\\s+(.+)/)||line.match(/^\\d+[.)]\\s+(.+)/);
 if(bullet){const type=/^\\d/.test(line)?"ol":"ul";if(!list||listType!==type){list=document.createElement(type);listType=type;container.appendChild(list);}const li=document.createElement("li");li.textContent=bullet[1].replace(/\\*\\*/g,"");list.appendChild(li);continue;}
 list=null;listType="";
 const p=document.createElement("p");
 const parts=line.split(/(\\*\\*[^*]+\\*\\*)/g);
 parts.forEach(part=>{if(part.startsWith("**")&&part.endsWith("**")){const strong=document.createElement("strong");strong.textContent=part.slice(2,-2);p.appendChild(strong);}else p.appendChild(document.createTextNode(part));});
 container.appendChild(p);
}
}
let chatGeneration=0;
let chatHistory=[];
function buildConversationQuestion(current){const recent=chatHistory.slice(-6).map(item=>(item.role==="user"?"USER: ":"ATLAS: ")+String(item.content||"").slice(0,500));return recent.length?"RECENT CONVERSATION (context only):\n"+recent.join("\n")+"\n\nCURRENT QUESTION:\n"+current:current;}
function addMessage(role,text){const el=document.createElement("div");el.className="mp-message "+role;const label=document.createElement("small");label.textContent=role==="user"?"YOU":"FINANCIAL ASSISTANT";const body=document.createElement("div");if(role==="assistant")renderAnswer(body,text);else body.textContent=text;el.append(label,body);$("mpMessages").appendChild(el);$("mpMessages").scrollTop=$("mpMessages").scrollHeight;return el;}
