function renderAssets(items){const host=$("mpAssets");host.replaceChildren();items.forEach(a=>{const row=document.createElement("div");row.className="mp-asset";const sym=document.createElement("div");sym.className="mp-symbol";sym.textContent=a.short;const middle=document.createElement("div");middle.className="mp-asset-main";const name=document.createElement("div");name.className="mp-asset-name";name.textContent=a.name;const note=document.createElement("div");note.className="mp-asset-note";note.textContent=a.error?"Unavailable: "+a.error:"24h market volume "+usd(a.volume)+" · updated "+(a.asOf?new Date(a.asOf).toLocaleTimeString():"time unavailable");middle.append(name,note);const right=document.createElement("div");right.className="mp-asset-price";const price=document.createElement("div");price.textContent=usd(a.price);const change=document.createElement("div");change.className="mp-asset-note "+(a.change>0?"mp-up":a.change<0?"mp-down":"");change.textContent=Number.isFinite(a.change)?(a.change>0?"+":"")+a.change.toFixed(2)+"% · 24h":"No quote";right.append(price,change);row.append(sym,middle,right);host.append(row);});const foot=document.createElement("p");foot.className="mp-status";foot.textContent="Source: CoinPaprika with Binance spot fallback · refreshed "+new Date().toLocaleTimeString()+" · aggregated USD quotes may be delayed.";host.append(foot);const promptHost=$("mpAssetPrompts");if(promptHost){promptHost.replaceChildren();const ranked=items.filter(x=>!x.error&&Number.isFinite(x.volume)).sort((a,b)=>b.volume-a.volume).slice(0,3);if(ranked.length){const heading=document.createElement("div");heading.className="mp-title";heading.textContent="Follow-ups · highest 24h quote volume";promptHost.appendChild(heading);const wrap=document.createElement("div");wrap.className="mp-prompts";ranked.forEach(a=>{const b=document.createElement("button");b.type="button";b.className="mp-prompt";b.textContent="Analyze "+a.short+" · "+usd(a.volume);b.addEventListener("click",()=>{ $("mpQuestion").value="Analyze "+a.name+" ("+a.symbol+") using the latest price, 24-hour change and quote volume. Explain plausible drivers only when supported by available data, give bull and bear scenarios, and list invalidation conditions. State source and timestamp; do not invent news.";setView("ai");$("mpQuestion").focus();});wrap.appendChild(b);});promptHost.appendChild(wrap);}}}
